//计算每一行的数锯长度 开机用
static void Compute_Array_Rows_Data_Num(void)
{

	uint8_t FF_Num = 0;
    uint8_t i;
    uint16_t j;
    //aaa[0][0] = 0;
	for(i=0;i<Array_ROW_NUM;i++)
	{
		for(j=0;j<Array_COLUMN_NUM;j++)
		{
			if(Array[i][j]==0xff)
			{
				FF_Num++;
			}
			else
			{
				FF_Num = 0;
			}
			if(FF_Num>=3)
			{
                Array_Rows_Data_Num[i] = j+1;//记录该行的数锯长度
				FF_Num = 0;
				break;
			}
		}
	}
}


